// 辅助函数：根据合作主体ID获取相关数据
export function getEnterpriseById(id: string): Enterprise | undefined {
  return enterprises.find(e => e.id === id)
}

export function getPartnerById(id: string): Partner | undefined {
  return partners.find(p => p.id === id)
}

export function getAgreementById(id: string): Agreement | undefined {
  return agreements.find(a => a.id === id)
}

export function getProjectById(id: string): Project | undefined {
  return projects.find(p => p.id === id)
}

export function getExpertById(id: string): Expert | undefined {
  return experts.find(e => e.id === id)
}

export function getActivityById(id: string): Activity | undefined {
  return activities.find(a => a.id === id)
}

export function getAchievementById(id: string): Achievement | undefined {
  return achievements.find(a => a.id === id)
}

export function getAgreementsByPartnerId(partnerId: string): Agreement[] {
  return agreements.filter(a => a.partnerId === partnerId)
}

export function getProjectsByPartnerId(partnerId: string): Project[] {
  return projects.filter(p => p.partnerId === partnerId)
}

export function getExpertsByPartnerId(partnerId: string): Expert[] {
  return experts.filter(e => e.partnerId === partnerId)
}

export function getAchievementsByPartnerId(partnerId: string): Achievement[] {
  return achievements.filter(a => a.partnerId === partnerId)
}


