export function getTalentProfileById(id: string): TalentProfile | undefined {
  return talentProfiles.find(t => t.id === id)
}

export function getEmploymentCaseById(id: string): EmploymentCase | undefined {
  return employmentCases.find(e => e.id === id)
}

export function getJobBrandById(id: string): JobBrand | undefined {
  return jobBrands.find(j => j.id === id)
}

export function getMajorBrandById(id: string): MajorBrand | undefined {
  return majorBrands.find(m => m.id === id)
}

export function getTeacherBrandById(id: string): TeacherBrand | undefined {
  return teacherBrands.find(t => t.id === id)
}

export function getCultureBrandById(id: string): CultureBrand | undefined {
  return cultureBrands.find(c => c.id === id)
}

export function getBrandTopicById(id: string): BrandTopic | undefined {
  return brandTopics.find(b => b.id === id)
}

